#include "unity.h"
#include <stdio.h>
#include <string.h>
#include "sd_popup.h"
#include "status_view.h"
#include "ui_state_machine.h"

void setUp(void)   {}
void tearDown(void) {}

/* Shared instances reused across tests */
static ui_state_t s;
static ui_state_t before;
static sd_popup_t pop;
static char       msg[96];

/* Every status text Jack sends, plus odd ones */
static const char *const k_texts[] = { "No Card", "Card Not Ready", "Ready", "Card Error", "Card Full",
                                       "USB mode", "Recording", "Playing", "Paused", "Ready (fake)",
                                       "...", "", "Something new", NULL };
#define K_TEXTS     (sizeof(k_texts) / sizeof(k_texts[0]))

static const uint8_t k_files[] = { 0U, 1U, 255U };
#define K_FILES     (sizeof(k_files) / sizeof(k_files[0]))

/* Helper — a status as Jack sends it (have_status set, idle) */
static sv_sd_in_t sd_in(bool present, bool mounted, const char *text)
{
    sv_sd_in_t in = { true, present, mounted, false, false, 0U, text, "", false };
    return in;
}

/* Helper — one of the flag mixes the loops walk: have_status,
 * card_present, mounted, msc_mode, recording, fx_busy (bits 0..5) and
 * playing (0..3, 3 = preparing) */
static sv_sd_in_t sd_mix(unsigned bits, uint8_t playing, const char *text)
{
    sv_sd_in_t in = { (bits & 1U) != 0U, (bits & 2U) != 0U, (bits & 4U) != 0U, (bits & 8U) != 0U,
                      (bits & 16U) != 0U, playing, text, "", (bits & 32U) != 0U };
    return in;
}

/* Helper — what one event does to s, as the start sdp_start_of() sees */
static sdp_start_t step(ui_event_t e)
{
    before = s;
    ui_process_event(&s, e);
    return sdp_start_of(&before, &s);
}

/* The reason words of the footer notice (sv_refusal_text without its
 * "REC: " / "PLAY: ") for each pop-up reason */
static const char *footer_words(sdp_reason_t r)
{
    switch (r) {
        case SDP_ON_PC:      return "SD CARD ON PC";
        case SDP_NO_CARD:    return "NO SD CARD";
        case SDP_NO_FILES:   return "NO RECORDINGS";
        case SDP_FULL:       return "SD CARD FULL";
        case SDP_NOT_READY:  return "SD NOT READY";
        case SDP_CARD_ERROR: return "SD CARD ERROR";
        case SDP_FAILED:     return "TRY AGAIN";
        default:             return "?";
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — What a step starts
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_every_playback_pair(void)
{
    /* Row = before, column = after: N none, R record, P play */
    static const char want[4][4] = {
        /* after:      IDLE RECORDING PLAYING PAUSED */
        /* IDLE      */ { 'N', 'R', 'P', 'N' },
        /* RECORDING */ { 'N', 'N', 'N', 'N' },
        /* PLAYING   */ { 'N', 'R', 'N', 'N' },     /* PLAYING -> PLAYING: a replay */
        /* PAUSED    */ { 'N', 'R', 'N', 'N' },     /* PAUSED -> PLAYING: a resume */
    };
    ui_state_t a, b;

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            ui_init(&a);
            ui_init(&b);
            a.playback = (playback_state_t)i;
            b.playback = (playback_state_t)j;
            sdp_start_t got = sdp_start_of(&a, &b);
            char c = (got == SDP_START_RECORD) ? 'R' : (got == SDP_START_PLAY) ? 'P' : 'N';
            snprintf(msg, sizeof(msg), "before %d after %d", i, j);
            TEST_ASSERT_EQUAL_INT_MESSAGE(want[i][j], c, msg);
        }
    }
}

void test_A02_rec_button_starts_from_idle_playing_and_paused(void)
{
    static const playback_state_t from[] = { PLAYBACK_IDLE, PLAYBACK_PLAYING, PLAYBACK_PAUSED };

    for (size_t i = 0U; i < sizeof(from) / sizeof(from[0]); i++) {
        ui_init(&s);
        s.playback = from[i];
        TEST_ASSERT_EQUAL_INT(SDP_START_RECORD, step(EVENT_BTN_RECORD));
    }
    /* REC while recording is a stop */
    ui_init(&s);
    s.playback = PLAYBACK_RECORDING;
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_BTN_RECORD));
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
}

void test_A03_play_button_starts_only_from_idle(void)
{
    ui_init(&s);
    TEST_ASSERT_EQUAL_INT(SDP_START_PLAY, step(EVENT_BTN_PLAYPAUSE));
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_BTN_PLAYPAUSE));    /* pause */
    TEST_ASSERT_EQUAL(PLAYBACK_PAUSED, s.playback);
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_BTN_PLAYPAUSE));    /* resume */
    TEST_ASSERT_EQUAL(PLAYBACK_PLAYING, s.playback);

    ui_init(&s);
    s.playback = PLAYBACK_RECORDING;                                     /* PLAY does nothing then */
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_BTN_PLAYPAUSE));
}

void test_A04_screen_taps_start_too(void)
{
    /* The Record screen's start row, and the Play screen's play button */
    ui_init(&s);
    s.screen = UI_SCREEN_RECORD;
    TEST_ASSERT_EQUAL_INT(SDP_START_RECORD, step(EVENT_RECORD_START));
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_RECORD_STOP));

    ui_init(&s);
    s.screen = UI_SCREEN_PLAY;
    TEST_ASSERT_EQUAL_INT(SDP_START_PLAY, step(EVENT_PLAY_START));
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, step(EVENT_PLAY_REPLAY));     /* already playing */

    ui_init(&s);
    s.screen = UI_SCREEN_PLAY;
    TEST_ASSERT_EQUAL_INT(SDP_START_PLAY, step(EVENT_PLAY_REPLAY));     /* from idle */
}

void test_A05_null_is_none(void)
{
    ui_init(&s);
    s.playback = PLAYBACK_RECORDING;
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, sdp_start_of(NULL, &s));
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, sdp_start_of(&s, NULL));
    TEST_ASSERT_EQUAL_INT(SDP_START_NONE, sdp_start_of(NULL, NULL));
}

void test_A06_no_other_input_ever_starts_anything(void)
{
    /* Every event on every screen in every transport state: only the REC
     * and PLAY inputs start something, so nothing else is ever held back
     * by the pre-check. Fault and Debug never start anything. REC starts
     * a recording from every screen but those two, whenever it is not
     * already recording. */
    for (int sc = 0; sc < (int)UI_SCREEN_COUNT; sc++) {
        for (int pb = (int)PLAYBACK_IDLE; pb <= (int)PLAYBACK_PAUSED; pb++) {
            for (int ev = 0; ev < (int)EVENT_NONE; ev++) {
                ui_init(&s);
                s.screen   = (ui_screen_t)sc;
                s.playback = (playback_state_t)pb;
                sdp_start_t got = step((ui_event_t)ev);
                bool        rec = (ev == (int)EVENT_BTN_RECORD || ev == (int)EVENT_RECORD_START);
                bool        ply = (ev == (int)EVENT_BTN_PLAYPAUSE || ev == (int)EVENT_PLAY_START ||
                                   ev == (int)EVENT_PLAY_REPLAY);
                bool        modal = (sc == (int)UI_SCREEN_FAULT || sc == (int)UI_SCREEN_DEBUG);

                snprintf(msg, sizeof(msg), "screen %d playback %d event %d", sc, pb, ev);
                if (got == SDP_START_RECORD) {
                    TEST_ASSERT_TRUE_MESSAGE(rec && !modal, msg);
                } else if (got == SDP_START_PLAY) {
                    TEST_ASSERT_TRUE_MESSAGE(ply && !modal, msg);
                }
                if (ev == (int)EVENT_BTN_RECORD && !modal && pb != (int)PLAYBACK_RECORDING) {
                    TEST_ASSERT_EQUAL_INT_MESSAGE(SDP_START_RECORD, got, msg);
                }
            }
        }
    }
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — Pre-check
 * ═══════════════════════════════════════════════════════════════════════ */

void test_B01_each_status(void)
{
    sv_sd_in_t no_card   = sd_in(false, false, "No Card");
    sv_sd_in_t ready     = sd_in(true,  true,  "Ready");
    sv_sd_in_t full      = sd_in(true,  false, "Card Full");
    sv_sd_in_t not_ready = sd_in(true,  false, "Card Not Ready");
    sv_sd_in_t error     = sd_in(true,  false, "Card Error");
    sv_sd_in_t on_pc     = sd_in(true,  false, "USB mode");
    on_pc.msc_mode = true;

    for (int rec = 0; rec <= 1; rec++) {
        TEST_ASSERT_EQUAL_INT(SDP_NO_CARD,    sdp_precheck(rec != 0, &no_card, 0U));
        TEST_ASSERT_EQUAL_INT(SDP_OK,         sdp_precheck(rec != 0, &ready, 3U));
        TEST_ASSERT_EQUAL_INT(SDP_FULL,       sdp_precheck(rec != 0, &full, 3U));
        TEST_ASSERT_EQUAL_INT(SDP_NOT_READY,  sdp_precheck(rec != 0, &not_ready, 0U));
        TEST_ASSERT_EQUAL_INT(SDP_CARD_ERROR, sdp_precheck(rec != 0, &error, 3U));
        TEST_ASSERT_EQUAL_INT(SDP_ON_PC,      sdp_precheck(rec != 0, &on_pc, 0U));
    }
    /* An empty card: REC makes the first recording, PLAY has nothing */
    TEST_ASSERT_EQUAL_INT(SDP_OK,       sdp_precheck(true,  &ready, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, sdp_precheck(false, &ready, 0U));
}

void test_B02_no_status_yet_lets_jack_decide(void)
{
    sv_sd_in_t in = sd_in(false, false, "No Card");

    in.have_status = false;
    in.msc_mode    = true;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(false, &in, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, NULL, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(false, NULL, 0U));
}

void test_B03_a_card_in_use_is_there(void)
{
    /* REC while a file plays or is paused: the UI stops it first, then
     * records, so the pre-check must not stand in the way */
    sv_sd_in_t in = sd_in(true, true, "Playing");

    in.playing = 1U;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 0U));
    in.playing = 2U;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 0U));
    in = sd_in(true, true, "Recording");
    in.recording = true;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(false, &in, 0U));
}

void test_B04_usb_mode_wins(void)
{
    for (unsigned bits = 0U; bits < 64U; bits++) {
        for (uint8_t playing = 0U; playing <= SV_PLAYING_PREPARING; playing++) {
            for (size_t t = 0U; t < K_TEXTS; t++) {
                sv_sd_in_t in = sd_mix(bits | 1U | 8U, playing, k_texts[t]);   /* status + MSC */
                snprintf(msg, sizeof(msg), "bits 0x%02X playing %u text %u", bits, (unsigned)playing, (unsigned)t);
                TEST_ASSERT_EQUAL_INT_MESSAGE(SDP_ON_PC, sdp_precheck(true, &in, 1U), msg);
                TEST_ASSERT_EQUAL_INT_MESSAGE(SDP_ON_PC, sdp_precheck(false, &in, 1U), msg);
            }
        }
    }
}

void test_B05_an_idle_card_is_refused_exactly_when_jack_would(void)
{
    /* Jack records only on a mounted card and plays only one with files
     * (storage_status_can_record / can_play), and refuses everything in
     * USB mode. With a status in and the card idle, the pre-check lets a
     * start through exactly then. */
    unsigned cases = 0U;

    for (unsigned bits = 0U; bits < 32U; bits++) {
        sv_sd_in_t probe = sd_mix(bits, 0U, NULL);
        if (!probe.have_status || probe.recording) {
            continue;                           /* not idle, or nothing known */
        }
        for (size_t t = 0U; t < K_TEXTS; t++) {
            for (size_t n = 0U; n < K_FILES; n++) {
                for (int rec = 0; rec <= 1; rec++) {
                    sv_sd_in_t in = sd_mix(bits, 0U, k_texts[t]);
                    bool jack_ok = !in.msc_mode && in.card_present && in.mounted &&
                                   (rec != 0 || k_files[n] > 0U);
                    snprintf(msg, sizeof(msg), "bits 0x%02X text %u files %u rec %d", bits, (unsigned)t,
                             (unsigned)k_files[n], rec);
                    TEST_ASSERT_EQUAL_INT_MESSAGE(jack_ok, sdp_precheck(rec != 0, &in, k_files[n]) == SDP_OK,
                                                  msg);
                    cases++;
                }
            }
        }
    }
    TEST_ASSERT_EQUAL_UINT(8U * K_TEXTS * K_FILES * 2U, cases);
}

void test_B06_first_match_order(void)
{
    sv_sd_in_t in;

    /* No card beats what a stale text or mounted flag says */
    in = sd_in(false, true, "Card Full");
    TEST_ASSERT_EQUAL_INT(SDP_NO_CARD, sdp_precheck(true, &in, 3U));
    /* Mounted beats the text: Jack only words a card that is not mounted */
    in = sd_in(true, true, "Card Full");
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 3U));
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, sdp_precheck(false, &in, 0U));
    /* Unknown or missing text on a card that is not mounted: an error */
    in = sd_in(true, false, NULL);
    TEST_ASSERT_EQUAL_INT(SDP_CARD_ERROR, sdp_precheck(true, &in, 3U));
    in = sd_in(true, false, "Card Full ");                      /* not exactly "Card Full" */
    TEST_ASSERT_EQUAL_INT(SDP_CARD_ERROR, sdp_precheck(false, &in, 3U));
}

void test_B08_a_card_preparing_or_making_effect_files_is_in_use(void)
{
    /* PLAY while Jack makes the file waited for (playing 3), or REC while
     * he makes effect files in the background (fx_busy): the card is in
     * use, so it is there; Jack stops or drops that work himself. */
    sv_sd_in_t in = sd_in(true, true, "Preparing");

    in.playing = SV_PLAYING_PREPARING;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 3U));
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(false, &in, 3U));
    in = sd_in(true, true, "Ready");
    in.fx_busy = true;
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &in, 3U));
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(false, &in, 0U));
}

void test_B07_256_files_are_not_no_recordings(void)
{
    /* Jack counts every file on the card now. The count is a uint16_t all
     * the way, so 256 files never wrap to 0 ("NO RECORDINGS"). */
    sv_sd_in_t ready = sd_in(true, true, "Ready");

    TEST_ASSERT_EQUAL_INT(SDP_OK,     sdp_precheck(false, &ready, 256U));
    TEST_ASSERT_EQUAL_INT(SDP_OK,     sdp_precheck(false, &ready, 65535U));
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(false, &ready, 256U));
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(false, &ready, 512U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — Jack's refusals
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_refused_although_the_status_looked_fine(void)
{
    sv_sd_in_t ready = sd_in(true, true, "Ready");
    sv_sd_in_t busy  = sd_in(true, true, "Playing");
    busy.playing = 1U;

    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(true,  &ready, 4U));   /* file would not open */
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(false, &ready, 4U));
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(true,  &ready, 0U));   /* REC on an empty card */
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(true,  &busy, 4U));    /* still busy */
    TEST_ASSERT_EQUAL_INT(SDP_FAILED, sdp_refusal_reason(false, NULL, 0U));     /* no status yet */
}

void test_C02_otherwise_the_precheck_reason(void)
{
    sv_sd_in_t no_card = sd_in(false, false, "No Card");
    sv_sd_in_t ready   = sd_in(true, true, "Ready");
    sv_sd_in_t full    = sd_in(true, false, "Card Full");

    TEST_ASSERT_EQUAL_INT(SDP_NO_CARD,  sdp_refusal_reason(true,  &no_card, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, sdp_refusal_reason(false, &ready, 0U));
    TEST_ASSERT_EQUAL_INT(SDP_FULL,     sdp_refusal_reason(false, &full, 2U));
}

void test_C03_every_status_agrees_with_the_footer_notice(void)
{
    /* The footer says "REC: <words>" for 3 s while the pop-up shows: for
     * every status, file count and command both give the same reason */
    unsigned cases = 0U;

    for (unsigned bits = 0U; bits < 64U; bits++) {
        for (uint8_t playing = 0U; playing <= SV_PLAYING_PREPARING; playing++) {
            for (size_t t = 0U; t < K_TEXTS; t++) {
                for (size_t n = 0U; n < K_FILES; n++) {
                    for (int rec = 0; rec <= 1; rec++) {
                        sv_sd_in_t   in  = sd_mix(bits, playing, k_texts[t]);
                        sdp_reason_t why = sdp_refusal_reason(rec != 0, &in, k_files[n]);
                        char want[40];
                        snprintf(want, sizeof(want), "%s%s", rec ? "REC: " : "PLAY: ", footer_words(why));
                        snprintf(msg, sizeof(msg), "bits 0x%02X playing %u text %u files %u rec %d", bits,
                                 (unsigned)playing, (unsigned)t, (unsigned)k_files[n], rec);
                        TEST_ASSERT_TRUE_MESSAGE(why != SDP_OK, msg);
                        TEST_ASSERT_EQUAL_STRING_MESSAGE(want, sv_refusal_text(rec != 0, &in, k_files[n]), msg);
                        cases++;
                    }
                }
            }
        }
    }
    TEST_ASSERT_EQUAL_UINT(64U * 4U * K_TEXTS * K_FILES * 2U, cases);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP D — Texts
 * ═══════════════════════════════════════════════════════════════════════ */

void test_D01_no_card_words(void)
{
    TEST_ASSERT_EQUAL_STRING("NO SD CARD",    sdp_line(SDP_NO_CARD, true, 0U));
    TEST_ASSERT_EQUAL_STRING("Insert a card", sdp_line(SDP_NO_CARD, true, 1U));
    TEST_ASSERT_EQUAL_STRING("to record",     sdp_line(SDP_NO_CARD, true, 2U));
    TEST_ASSERT_EQUAL_STRING("NO SD CARD",    sdp_line(SDP_NO_CARD, false, 0U));
    TEST_ASSERT_EQUAL_STRING("Insert a card", sdp_line(SDP_NO_CARD, false, 1U));
    TEST_ASSERT_EQUAL_STRING("to play",       sdp_line(SDP_NO_CARD, false, 2U));
}

void test_D02_every_reason_fits_the_box(void)
{
    /* Line 0 says what is wrong in upper case, line 1 what to do; every
     * line fits the box (SDP_TEXT_W) and so a size-2 line (20) */
    TEST_ASSERT_LESS_OR_EQUAL_UINT(20U, SDP_TEXT_W);
    for (int r = (int)SDP_ON_PC; r < (int)SDP_REASON_COUNT; r++) {
        for (int rec = 0; rec <= 1; rec++) {
            for (uint8_t line = 0U; line < SDP_LINES; line++) {
                const char *t = sdp_line((sdp_reason_t)r, rec != 0, line);
                snprintf(msg, sizeof(msg), "reason %d rec %d line %u", r, rec, (unsigned)line);
                TEST_ASSERT_NOT_NULL_MESSAGE(t, msg);
                TEST_ASSERT_LESS_OR_EQUAL_UINT_MESSAGE(SDP_TEXT_W, strlen(t), msg);
                if (line < 2U) {
                    TEST_ASSERT_TRUE_MESSAGE(t[0] != '\0', msg);
                }
                for (const char *c = t; *c != '\0'; c++) {
                    TEST_ASSERT_TRUE_MESSAGE(*c >= 0x20 && *c <= 0x7E, msg);         /* the panel's font */
                    if (line == 0U) {
                        TEST_ASSERT_FALSE_MESSAGE(*c >= 'a' && *c <= 'z', msg);
                    }
                }
            }
        }
    }
}

void test_D03_headline_is_the_footer_reason(void)
{
    /* Pop-up and footer use the same words, but for Jack's refusal of a
     * start the status had no reason for */
    for (int r = (int)SDP_ON_PC; r < (int)SDP_FAILED; r++) {
        for (int rec = 0; rec <= 1; rec++) {
            snprintf(msg, sizeof(msg), "reason %d rec %d", r, rec);
            TEST_ASSERT_EQUAL_STRING_MESSAGE(footer_words((sdp_reason_t)r),
                                             sdp_line((sdp_reason_t)r, rec != 0, 0U), msg);
        }
    }
    TEST_ASSERT_EQUAL_STRING("COULD NOT RECORD", sdp_line(SDP_FAILED, true, 0U));
    TEST_ASSERT_EQUAL_STRING("COULD NOT PLAY",   sdp_line(SDP_FAILED, false, 0U));
    TEST_ASSERT_EQUAL_STRING("Please try again", sdp_line(SDP_FAILED, false, 1U));
    /* The command is named where the action depends on it */
    TEST_ASSERT_EQUAL_STRING("to record", sdp_line(SDP_ON_PC, true, 2U));
    TEST_ASSERT_EQUAL_STRING("to play",   sdp_line(SDP_ON_PC, false, 2U));
}

void test_D04_no_reason_or_line_out_of_range_is_empty(void)
{
    for (uint8_t line = 0U; line <= SDP_LINES; line++) {
        TEST_ASSERT_EQUAL_STRING("", sdp_line(SDP_OK, true, line));
        TEST_ASSERT_EQUAL_STRING("", sdp_line(SDP_REASON_COUNT, false, line));
        TEST_ASSERT_EQUAL_STRING("", sdp_line((sdp_reason_t)200, true, line));
    }
    TEST_ASSERT_EQUAL_STRING("", sdp_line(SDP_NO_CARD, true, SDP_LINES));
    TEST_ASSERT_EQUAL_STRING("", sdp_line(SDP_NO_CARD, false, 255U));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP E — Showing and closing
 * ═══════════════════════════════════════════════════════════════════════ */

void test_E01_init_closed_and_null_safe(void)
{
    memset(&pop, 0xA5, sizeof(pop));
    sdp_init(&pop);
    TEST_ASSERT_FALSE(pop.open);
    TEST_ASSERT_EQUAL_INT(SDP_OK, pop.reason);
    TEST_ASSERT_FALSE(sdp_close_on_input(&pop));
    TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_HOME, 0U));

    sdp_init(NULL);
    TEST_ASSERT_FALSE(sdp_open(NULL, SDP_NO_CARD, true, UI_SCREEN_HOME, 0U));
    TEST_ASSERT_FALSE(sdp_close_on_input(NULL));
    TEST_ASSERT_FALSE(sdp_update(NULL, UI_SCREEN_HOME, 0U));
}

void test_E02_opens_with_its_words(void)
{
    sdp_init(&pop);
    TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_FILES, false, UI_SCREEN_PLAY, 5000U));
    TEST_ASSERT_TRUE(pop.open);
    TEST_ASSERT_FALSE(pop.record);
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, pop.reason);
    TEST_ASSERT_EQUAL(UI_SCREEN_PLAY, pop.screen);
    TEST_ASSERT_EQUAL_UINT32(5000U + SDP_SHOW_MS, pop.until_ms);
}

void test_E03_shows_for_exactly_3_s_across_the_tick_wrap(void)
{
    /* Open from t0 to t0 + 2999 ms, closed at t0 + 3000 and it stays
     * closed. From the fourth start on, the tick count passes 0x80000000
     * or wraps to 0 while it shows */
    static const uint32_t t0s[] = { 0U, 1U, 123456U, 0x7FFFFFFFU - 999U, 0x7FFFFFFFU,
                                    0xFFFFFFFFU - SDP_SHOW_MS, 0xFFFFFFFFU - 999U, 0xFFFFF000U,
                                    0xFFFFFFFFU };

    TEST_ASSERT_EQUAL_UINT32(3000U, SDP_SHOW_MS);
    for (size_t i = 0U; i < sizeof(t0s) / sizeof(t0s[0]); i++) {
        sdp_init(&pop);
        TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_HOME, t0s[i]));
        for (uint32_t dt = 0U; dt <= 2U * SDP_SHOW_MS; dt++) {
            bool closed_now = sdp_update(&pop, UI_SCREEN_HOME, t0s[i] + dt);
            if (closed_now != (dt == SDP_SHOW_MS) || pop.open != (dt < SDP_SHOW_MS)) {
                snprintf(msg, sizeof(msg), "t0 0x%08lX dt %lu", (unsigned long)t0s[i], (unsigned long)dt);
                TEST_FAIL_MESSAGE(msg);
            }
        }
    }
}

void test_E04_any_input_closes_it_once(void)
{
    sdp_init(&pop);
    TEST_ASSERT_TRUE(sdp_open(&pop, SDP_ON_PC, true, UI_SCREEN_RECORD, 0U));
    TEST_ASSERT_TRUE(sdp_close_on_input(&pop));         /* the screen under it comes back */
    TEST_ASSERT_FALSE(pop.open);
    TEST_ASSERT_FALSE(sdp_close_on_input(&pop));        /* nothing more to close */
    TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_RECORD, 10U));
}

void test_E05_a_screen_change_closes_it(void)
{
    static const ui_screen_t other[] = { UI_SCREEN_HOME, UI_SCREEN_PLAY, UI_SCREEN_FAULT, UI_SCREEN_DEBUG };

    for (size_t i = 0U; i < sizeof(other) / sizeof(other[0]); i++) {
        sdp_init(&pop);
        TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_RECORD, 100U));
        TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_RECORD, 200U));     /* same screen: stays */
        TEST_ASSERT_TRUE(sdp_update(&pop, other[i], 300U));             /* a fault, Debug, Home ... */
        TEST_ASSERT_FALSE(pop.open);
        TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_RECORD, 400U));     /* and it stays closed */
    }
}

void test_E06_nothing_opens_without_a_reason_or_over_fault_and_debug(void)
{
    sdp_init(&pop);
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_OK, true, UI_SCREEN_HOME, 0U));
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_REASON_COUNT, true, UI_SCREEN_HOME, 0U));
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_FAULT, 0U));
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_DEBUG, 0U));
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_COUNT, 0U));
    TEST_ASSERT_FALSE(pop.open);

    /* Every screen with the header and footer takes it */
    for (int sc = 0; sc < (int)UI_SCREEN_COUNT; sc++) {
        bool frame = (sc != (int)UI_SCREEN_FAULT && sc != (int)UI_SCREEN_DEBUG);
        sdp_init(&pop);
        TEST_ASSERT_EQUAL_INT(frame, sdp_open(&pop, SDP_FULL, false, (ui_screen_t)sc, 0U));
        TEST_ASSERT_EQUAL_INT(frame, pop.open);
    }

    /* A refused open leaves the one showing as it was */
    sdp_init(&pop);
    TEST_ASSERT_TRUE(sdp_open(&pop, SDP_FULL, true, UI_SCREEN_HOME, 0U));
    TEST_ASSERT_FALSE(sdp_open(&pop, SDP_NO_CARD, false, UI_SCREEN_FAULT, 1000U));
    TEST_ASSERT_TRUE(pop.open);
    TEST_ASSERT_EQUAL_INT(SDP_FULL, pop.reason);
    TEST_ASSERT_TRUE(pop.record);
    TEST_ASSERT_EQUAL_UINT32(SDP_SHOW_MS, pop.until_ms);
}

void test_E07_opening_again_gives_new_words_and_a_new_3_s(void)
{
    sdp_init(&pop);
    TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_HOME, 0U));
    TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_FILES, false, UI_SCREEN_HOME, 2500U));
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, pop.reason);
    TEST_ASSERT_FALSE(pop.record);
    TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_HOME, 3000U));         /* the first 3 s no longer count */
    TEST_ASSERT_FALSE(sdp_update(&pop, UI_SCREEN_HOME, 5499U));
    TEST_ASSERT_TRUE(sdp_update(&pop, UI_SCREEN_HOME, 5500U));
}

void test_E08_rec_again_once_a_card_is_in_records(void)
{
    /* The firmware's order: REC with no card leaves the UI where it was
     * and opens the pop-up; the card goes in; REC again closes the
     * pop-up, which does not use up the press, and records */
    sv_sd_in_t   no_card = sd_in(false, false, "No Card");
    sv_sd_in_t   ready   = sd_in(true, true, "Ready");
    sdp_start_t  start;
    sdp_reason_t why;

    ui_init(&s);                                        /* Home, idle */
    sdp_init(&pop);
    start = step(EVENT_BTN_RECORD);
    TEST_ASSERT_EQUAL_INT(SDP_START_RECORD, start);
    why = sdp_precheck(true, &no_card, 0U);
    TEST_ASSERT_EQUAL_INT(SDP_NO_CARD, why);
    TEST_ASSERT_TRUE(sdp_open(&pop, why, true, before.screen, 1000U));
    s.screen   = before.screen;                         /* nothing starts: no "Recording" */
    s.playback = before.playback;
    TEST_ASSERT_EQUAL(UI_SCREEN_HOME, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
    TEST_ASSERT_FALSE(sdp_update(&pop, s.screen, 2000U));

    TEST_ASSERT_TRUE(sdp_close_on_input(&pop));         /* REC again, a card in now */
    start = step(EVENT_BTN_RECORD);
    TEST_ASSERT_EQUAL_INT(SDP_START_RECORD, start);
    TEST_ASSERT_EQUAL_INT(SDP_OK, sdp_precheck(true, &ready, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_RECORDING, s.playback);
    TEST_ASSERT_FALSE(pop.open);
}

void test_E09_a_tap_on_the_box_only_closes_it(void)
{
    /* The box hides live targets (Home tiles, Volume buttons, the Play
     * button): a tap on it is used up; one off it is an ordinary input */
    static const uint16_t on[][2]  = { { SDP_BOX_X, SDP_BOX_Y },
                                       { SDP_BOX_X + SDP_BOX_W - 1U, SDP_BOX_Y + SDP_BOX_H - 1U },
                                       { SDP_BOX_X + SDP_BOX_W / 2U, SDP_BOX_Y + SDP_BOX_H / 2U } };
    static const uint16_t off[][2] = { { SDP_BOX_X - 1U, SDP_BOX_Y }, { SDP_BOX_X + SDP_BOX_W, SDP_BOX_Y },
                                       { SDP_BOX_X, SDP_BOX_Y - 1U }, { SDP_BOX_X, SDP_BOX_Y + SDP_BOX_H },
                                       { MENU_X + 10U, MENU_Y0 + 10U },       /* the Record start row */
                                       { 0U, 0U }, { SCREEN_W - 1U, SCREEN_H - 1U } };

    for (size_t i = 0U; i < sizeof(on) / sizeof(on[0]); i++) {
        sdp_init(&pop);
        TEST_ASSERT_FALSE(sdp_tap_on_box(&pop, on[i][0], on[i][1]));        /* nothing showing */
        TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_CARD, false, UI_SCREEN_PLAY, 0U));
        TEST_ASSERT_TRUE(sdp_tap_on_box(&pop, on[i][0], on[i][1]));
        TEST_ASSERT_FALSE(pop.open);
    }
    for (size_t i = 0U; i < sizeof(off) / sizeof(off[0]); i++) {
        sdp_init(&pop);
        TEST_ASSERT_TRUE(sdp_open(&pop, SDP_NO_CARD, true, UI_SCREEN_RECORD, 0U));
        snprintf(msg, sizeof(msg), "tap %u,%u", (unsigned)off[i][0], (unsigned)off[i][1]);
        TEST_ASSERT_FALSE_MESSAGE(sdp_tap_on_box(&pop, off[i][0], off[i][1]), msg);
        TEST_ASSERT_TRUE_MESSAGE(pop.open, msg);                             /* left to the input */
    }
    TEST_ASSERT_FALSE(sdp_tap_on_box(NULL, SDP_BOX_X, SDP_BOX_Y));
}

void test_E10_the_box_sits_in_the_body_below_the_start_row(void)
{
    /* Between the title bar and the footer; the Record screen's start
     * row ("Insert SD card") stays in view above it; the widest line fits
     * inside with 8 px each side (size 2: 12 px a letter) */
    TEST_ASSERT_TRUE(SDP_BOX_Y >= MENU_Y0 + MENU_H);
    TEST_ASSERT_TRUE(SDP_BOX_Y + SDP_BOX_H <= STATUS_BAR_Y);
    TEST_ASSERT_TRUE(SDP_BOX_X + SDP_BOX_W <= SCREEN_W);
    TEST_ASSERT_TRUE(SDP_TEXT_W * 12U + 2U * 8U <= SDP_BOX_W);
    TEST_ASSERT_TRUE(SDP_LINES * 16U < SDP_BOX_H);
}

void test_E11_a_refused_start_stays_on_its_screen_under_the_popup(void)
{
    /* The board: no card, Home, REC. The step went to the Record screen,
     * the UI goes back to Home, so the pop-up must cover Home. Opened over
     * Record it closed on the next pass, before it was ever drawn: only
     * the beep and the footer notice were left. */
    sv_sd_in_t   no_card = sd_in(false, false, "No Card");
    sdp_reason_t why;
    unsigned     cases = 0U;

    ui_init(&s);
    sdp_init(&pop);
    TEST_ASSERT_EQUAL_INT(SDP_START_RECORD, step(EVENT_BTN_RECORD));
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.screen);
    why = sdp_precheck(true, &no_card, 0U);
    TEST_ASSERT_TRUE(sdp_refuse(&pop, why, true, &s, before.screen, before.playback, 1000U));
    TEST_ASSERT_EQUAL(UI_SCREEN_HOME, s.screen);                    /* no "Recording" */
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
    TEST_ASSERT_EQUAL(UI_SCREEN_HOME, pop.screen);
    TEST_ASSERT_FALSE(sdp_update(&pop, s.screen, 1001U));            /* the next pass: still open */
    TEST_ASSERT_TRUE(pop.open);
    TEST_ASSERT_EQUAL_STRING("NO SD CARD", sdp_line(pop.reason, pop.record, 0U));

    /* The same for every start on every screen with the frame, from every
     * transport: the UI is back where the input found it, and the pop-up
     * over that screen lasts its 3 s */
    for (int sc = 0; sc < (int)UI_SCREEN_COUNT; sc++) {
        if (sc == (int)UI_SCREEN_FAULT || sc == (int)UI_SCREEN_DEBUG) {
            continue;                                   /* nothing starts there (A06) */
        }
        for (int pb = (int)PLAYBACK_IDLE; pb <= (int)PLAYBACK_PAUSED; pb++) {
            for (int ev = 0; ev < (int)EVENT_NONE; ev++) {
                ui_init(&s);
                s.screen   = (ui_screen_t)sc;
                s.playback = (playback_state_t)pb;
                sdp_start_t start = step((ui_event_t)ev);
                if (start == SDP_START_NONE) {
                    continue;
                }
                bool rec = (start == SDP_START_RECORD);
                snprintf(msg, sizeof(msg), "screen %d playback %d event %d", sc, pb, ev);
                sdp_init(&pop);
                TEST_ASSERT_TRUE_MESSAGE(sdp_refuse(&pop, SDP_NO_CARD, rec, &s, before.screen, before.playback,
                                                    5000U), msg);
                TEST_ASSERT_EQUAL_INT_MESSAGE(sc, s.screen, msg);
                TEST_ASSERT_EQUAL_INT_MESSAGE(pb, s.playback, msg);
                TEST_ASSERT_EQUAL_INT_MESSAGE(sc, pop.screen, msg);
                TEST_ASSERT_EQUAL_INT_MESSAGE(rec, pop.record, msg);
                TEST_ASSERT_FALSE_MESSAGE(sdp_update(&pop, s.screen, 5001U), msg);
                TEST_ASSERT_FALSE_MESSAGE(sdp_update(&pop, s.screen, 5000U + SDP_SHOW_MS - 1U), msg);
                TEST_ASSERT_TRUE_MESSAGE(sdp_update(&pop, s.screen, 5000U + SDP_SHOW_MS), msg);
                cases++;
            }
        }
    }
    /* REC from 7 screens x 3 transports, PLAY from 7 screens when idle,
     * the Record screen's start row x 3, Play's play and replay buttons */
    TEST_ASSERT_EQUAL_UINT(21U + 7U + 3U + 2U, cases);
}

void test_E12_a_refused_select_on_the_files_screen_stays_there(void)
{
    sv_sd_in_t ready = sd_in(true, true, "Ready");

    /* The firmware turns a select on the Files screen into the Play
     * screen and PLAY; refused, it stays on Files */
    ui_init(&s);
    s.screen = UI_SCREEN_FILE;
    before   = s;
    s.screen   = UI_SCREEN_PLAY;
    s.playback = PLAYBACK_PLAYING;
    TEST_ASSERT_EQUAL_INT(SDP_START_PLAY, sdp_start_of(&before, &s));
    sdp_init(&pop);
    TEST_ASSERT_TRUE(sdp_refuse(&pop, SDP_NO_CARD, false, &s, before.screen, before.playback, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_FILE, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
    TEST_ASSERT_FALSE(sdp_update(&pop, s.screen, 1U));
    TEST_ASSERT_TRUE(pop.open);

    /* With no recording listed nothing moves, but the select says why,
     * as PLAY does: an empty card is NO RECORDINGS */
    ui_init(&s);
    s.screen = UI_SCREEN_FILE;
    sdp_init(&pop);
    TEST_ASSERT_EQUAL_INT(SDP_NO_FILES, sdp_precheck(false, &ready, 0U));
    TEST_ASSERT_TRUE(sdp_refuse(&pop, SDP_NO_FILES, false, &s, UI_SCREEN_FILE, s.playback, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_FILE, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
    TEST_ASSERT_FALSE(sdp_update(&pop, s.screen, 1U));
    TEST_ASSERT_EQUAL_STRING("NO RECORDINGS", sdp_line(pop.reason, pop.record, 0U));
}

void test_E13_refuse_without_a_reason_changes_nothing(void)
{
    /* SDP_OK or a reason out of range: the start goes ahead, so neither
     * the state nor the pop-up changes */
    ui_init(&s);
    s.screen   = UI_SCREEN_RECORD;
    s.playback = PLAYBACK_RECORDING;
    sdp_init(&pop);
    TEST_ASSERT_FALSE(sdp_refuse(&pop, SDP_OK, true, &s, UI_SCREEN_HOME, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_FALSE(sdp_refuse(&pop, SDP_REASON_COUNT, true, &s, UI_SCREEN_HOME, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_RECORD, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_RECORDING, s.playback);
    TEST_ASSERT_FALSE(pop.open);

    /* No state: nothing opens either */
    TEST_ASSERT_FALSE(sdp_refuse(&pop, SDP_NO_CARD, true, NULL, UI_SCREEN_HOME, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_FALSE(pop.open);

    /* No pop-up: the state is still put back */
    TEST_ASSERT_FALSE(sdp_refuse(NULL, SDP_NO_CARD, true, &s, UI_SCREEN_HOME, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_HOME, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);

    /* Back on the fault or debug screen: put back, but no pop-up over it */
    s.playback = PLAYBACK_RECORDING;
    TEST_ASSERT_FALSE(sdp_refuse(&pop, SDP_NO_CARD, true, &s, UI_SCREEN_FAULT, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_EQUAL(UI_SCREEN_FAULT, s.screen);
    TEST_ASSERT_EQUAL(PLAYBACK_IDLE, s.playback);
    TEST_ASSERT_FALSE(sdp_refuse(&pop, SDP_NO_CARD, true, &s, UI_SCREEN_DEBUG, PLAYBACK_IDLE, 0U));
    TEST_ASSERT_FALSE(pop.open);
}

